// Generates dist-viewer/: the embeddable viewer, an installable npm package (`npm pack`).
//   mapping-viewer.js        framework-free core (createViewer, loadLibrary, screenTree...)
//   mapping-viewer-react.js  <MappingViewer/> wrapper (react, react/jsx-runtime and react-dom stay
//                            out: the host provides its own React)
//   *.js.map                 source maps (external), one per bundle
//   types/                   declarations (.d.ts) of the two entries, generated by tsc
//   package.json, README.md  the package manifest (exports "." and "./react") and the usage guide
// Each .js is self-contained (with Konva and the engine embedded): the host uses one OR the other.
// ESM on purpose: `dist-viewer/package.json` declares "type": "module".
// Minified, with maps: core ~ 275 kB (map ~ 1.5 MB) and React wrapper ~ 276 kB
// (map ~ 1.5 MB). The maps add no weight to the host site
// (the browser only downloads them with DevTools open).
// tsc runs first (and checks the types); if it fails, nothing is generated. After esbuild, the
// script checks that every file pointed to by `exports` exists.
import { execFileSync } from 'node:child_process';
import process from 'node:process';
import { access, copyFile, rm, writeFile } from 'node:fs/promises';
import { build } from 'esbuild';
import { packageJson } from './packageManifest.mjs';

const OUT = 'dist-viewer';

// Clean the output first: `.d.ts` files and maps from a previous version do not enter the package.
await rm(OUT, { recursive: true, force: true });

execFileSync(
  process.execPath,
  ['node_modules/typescript/bin/tsc', '-p', 'viewer/tsconfig.json'],
  {
    stdio: 'inherit',
  },
);

await build({
  entryPoints: {
    'mapping-viewer': 'viewer/index.ts',
    'mapping-viewer-react': 'viewer/react.tsx',
  },
  outdir: OUT,
  bundle: true,
  splitting: false,
  format: 'esm',
  platform: 'browser',
  target: 'es2022',
  external: ['react', 'react/jsx-runtime', 'react-dom'],
  jsx: 'automatic',
  // 'eof': the embedded Konva license notice goes to the end of the bundle.
  legalComments: 'eof',
  minify: true,
  sourcemap: true,
  logLevel: 'info',
});

await writeFile(`${OUT}/package.json`, `${JSON.stringify(packageJson, null, 2)}\n`);
await copyFile('viewer/PACKAGE-README.md', `${OUT}/README.md`);

/** The paths (strings) of `exports`, at any depth, plus the `types` field. */
function exportedFiles(value) {
  if (typeof value === 'string') return [value];
  return Object.values(value).flatMap(exportedFiles);
}

const missing = [];
for (const file of [...exportedFiles(packageJson.exports), packageJson.types]) {
  try {
    await access(`${OUT}/${file}`);
  } catch {
    missing.push(file);
  }
}
if (missing.length > 0) {
  process.stderr.write(
    `dist-viewer/package.json points to files the build did not generate: ${missing.join(', ')}\n`,
  );
  process.exit(1);
}
